export type TransactionStatus = 'LUNAS' | 'HUTANG';
export type TransactionCategory = 'IURAN' | 'TUNGGAKAN';

export interface Transaksi {
    id: string;
    timestamp: Date;
    wargaId: string;
    petugasId: string;
    amount: number;
    status: TransactionStatus;
    category?: TransactionCategory;
