import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/context/AuthContext';
import { loginAdmin, loginPetugas } from '@/services/api';

const UnifiedLoginPage: React.FC = () => {
    const [pin, setPin] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();
    const { loginAdmin: authLoginAdmin, loginPetugas: authLoginPetugas } = useAuth();

    const handleNumberClick = (num: string) => {
        if (pin.length < 8) {
            setPin(prev => prev + num);
            setError('');
        }
    };

    const handleDelete = () => {
        setPin(prev => prev.slice(0, -1));
    };

    const handleClear = () => {
        setPin('');
        setError('');
    };

    const handleSubmit = async () => {
        if (pin.length < 4) {
            setError('PIN minimal 4 digit.');
            return;
        }
        setLoading(true);
        setError('');

        try {
            // First try to login as Admin (since admins usually have 6-digit pins in our mock)
            const admin = await loginAdmin(pin);
            if (admin) {
                authLoginAdmin(admin);
                navigate('/admin/dashboard');
                return;
            }

            // If not admin, try petugas
            const petugas = await loginPetugas(pin);
            if (petugas) {
                authLoginPetugas(petugas);
                navigate('/petugas/dashboard');
                return;
            }

            // If both fail
            setError('PIN Tidak Terdaftar.');
            setPin('');

        } catch (err) {
            setError('Terjadi kesalahan koneksi.');
            setPin('');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center p-4 bg-slate-50 relative overflow-hidden">
            {/* Background elements */}
            <div className="absolute top-0 right-0 -mt-20 -mr-20 w-80 h-80 bg-emerald-100 rounded-full blur-3xl opacity-50"></div>
            <div className="absolute bottom-0 left-0 -mb-20 -ml-20 w-80 h-80 bg-blue-100 rounded-full blur-3xl opacity-50"></div>

            <div className="w-full max-w-sm relative z-10">
                <div className="text-center mb-10 animate-fade-in">
                    <div className="w-20 h-20 bg-slate-900 text-white rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-2xl -rotate-6 font-black text-3xl">SD</div>
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">SapaDesa</h1>
                    <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">Akses Sistem Terpadu</p>
                </div>

                <div className="bg-white/80 backdrop-blur-xl p-8 rounded-[3rem] shadow-2xl shadow-slate-200/60 border border-white animate-slide-in-up">
                    {/* PIN Display */}
                    <div className="mb-8 text-center">
                        <div className="flex justify-center gap-3 h-12 items-center">
                            {pin.length === 0 ? (
                                <span className="text-slate-300 font-bold uppercase tracking-widest text-xs">Masukkan PIN</span>
                            ) : (
                                pin.split('').map((_, i) => (
                                    <div key={i} className="w-4 h-4 rounded-full bg-emerald-500 shadow-lg shadow-emerald-500/30 animate-pulse"></div>
                                ))
                            )}
                        </div>
                        {error && (
                            <p className="mt-4 text-rose-500 font-black text-[10px] uppercase tracking-widest animate-shake">
                                {error}
                            </p>
                        )}
                    </div>

                    {/* Keypad Grid */}
                    <div className="grid grid-cols-3 gap-4">
                        {[1, 2, 3, 4, 5, 6, 7, 8, 9].map((num) => (
                            <button
                                key={num}
                                onClick={() => handleNumberClick(String(num))}
                                className="h-16 rounded-2xl bg-slate-50 text-2xl font-black text-slate-800 hover:bg-emerald-500 hover:text-white hover:scale-105 active:scale-95 transition-all duration-200 border border-slate-100"
                            >
                                {num}
                            </button>
                        ))}
                        <button
                            onClick={handleClear}
                            className="h-16 rounded-2xl bg-rose-50 text-rose-500 font-black text-[10px] uppercase tracking-widest hover:bg-rose-500 hover:text-white transition-all border border-rose-100"
                        >
                            C
                        </button>
                        <button
                            onClick={() => handleNumberClick('0')}
                            className="h-16 rounded-2xl bg-slate-50 text-2xl font-black text-slate-800 hover:bg-emerald-500 hover:text-white hover:scale-105 active:scale-95 transition-all duration-200 border border-slate-100"
                        >
                            0
                        </button>
                        <button
                            onClick={handleDelete}
                            className="h-16 rounded-2xl bg-slate-100 text-slate-500 flex items-center justify-center hover:bg-slate-200 transition-all border border-slate-200"
                        >
                            <i className="fa-solid fa-delete-left text-xl"></i>
                        </button>
                    </div>

                    <button
                        onClick={handleSubmit}
                        disabled={loading || pin.length < 4}
                        className="w-full mt-8 bg-slate-900 text-white py-5 rounded-[2rem] font-black uppercase tracking-widest text-xs shadow-xl shadow-slate-900/20 hover:bg-emerald-600 transition-all duration-300 disabled:opacity-30 disabled:hover:bg-slate-900 flex items-center justify-center gap-2"
                    >
                        {loading ? (
                            <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        ) : (
                            <>Verifikasi Akses <i className="fa-solid fa-circle-check"></i></>
                        )}
                    </button>
                </div>

                <div className="mt-8 text-center animate-fade-in delay-300">
                    <button onClick={() => navigate('/')} className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em] hover:text-emerald-500 transition-colors">
                        &larr; Kembali ke Beranda Publik
                    </button>
                </div>
            </div>

            <style>{`
                @keyframes shake {
                    0%, 100% { transform: translateX(0); }
                    25% { transform: translateX(-4px); }
                    75% { transform: translateX(4px); }
                }
                .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
            `}</style>
        </div>
    );
};

export default UnifiedLoginPage;

