export const createTransaksi = async (txData: any): Promise<Transaksi | null> => {
    const txId = `tx${Date.now()}`;
    const { data, error } = await supabase
        .from('transactions')
        .insert([{ ...txData, id: txId }])
        .select()
        .single();

    if (txData.status === 'HUTANG') {
        // Update hutang warga secara atomik
        const { data: warga } = await supabase.from('wargas').select('total_debt').eq('id', txData.wargaId).single();
        if (warga) {
            await supabase.from('wargas').update({ total_debt: warga.total_debt + txData.amount }).eq('id', txData.wargaId);
        }
    }
    return data;
};

export const getReports = async (f: { startDate: Date, endDate: Date }): Promise<any[]> => {
    const { data, error } = await supabase
        .from('transactions')
        .select(`
            *,
            wargas (name, dukuh_id, rt_id),
            petugases (name)
        `)
        .gte('timestamp', f.startDate.toISOString())
        .lte('timestamp', f.endDate.toISOString());

    if (error) return [];

    // Mapping kembali ke format yang diharapkan UI
    return data.map(tx => ({
        ...tx,
        wargaName: tx.wargas?.name || 'Warga Terhapus',
        petugasName: tx.petugases?.name || 'Sistem',
        dukuhName: 'Dukuh ...', // Diperlukan join lanjutan atau mapping lokal
        rtNumber: 'RT ...'
    }));
};

