export const deleteTransaksi = async (id: string) => {
    const { data: tx } = await supabase.from('transactions').select('*').eq('id', id).single();
    if (tx && tx.status === 'HUTANG') {
        const { data: warga } = await supabase.from('wargas').select('total_debt').eq('id', tx.wargaId).single();
        if (warga) {
            await supabase.from('wargas').update({ total_debt: Math.max(0, warga.total_debt - tx.amount) }).eq('id', tx.wargaId);
        }
    }
    await supabase.from('transactions').delete().eq('id', id);
};

